// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";
import {IAccessControl} from "../src/TimelockController.sol";
import {IERC165} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 seed) public {
        // WIDE admissible domain: any uint32 value selects the interface id under test,
        // XORed with the IAccessControl interface id so the discriminating id is reachable.
        bytes4 id = bytes4(uint32(bound(seed, 0, type(uint32).max))) ^ type(IAccessControl).interfaceId;

        // General rule: c reports support exactly for IAccessControl, IERC165 (and overridden ids).
        bool expected = (id == type(IAccessControl).interfaceId) || (id == type(IERC165).interfaceId);
        assertTrue(c.supportsInterface(id) == expected);
    }
}
